// Quotas in KiB.
const PLANS = {
  free: { quotaKiB: 524288 },
  team: { quotaKiB: 209715200 },
  archive: { quotaKiB: 2147483648 },
};

function quotaBytes(plan) {
  const entry = PLANS[plan];
  if (!entry) throw new Error('unknown plan: ' + plan);
  return entry.quotaKiB << 10;
}

module.exports = { PLANS, quotaBytes };
