const assert = require('node:assert');
const { quotaBytes } = require('../src/plans');
const { acceptUpload } = require('../src/upload');

test('free plan quota is 512 MiB', () => {
  assert.strictEqual(quotaBytes('free'), 512 * 1024 * 1024);
});

test('an upload past the quota is refused', () => {
  const account = { plan: 'free', files: [{ name: 'a.bin', size: 512 * 1024 * 1024 }] };
  assert.deepStrictEqual(acceptUpload(account, { name: 'b.txt', size: 1 }), { ok: false, reason: 'over quota' });
});

